import assert from'node:assert/strict';import{readFileSync}from'node:fs';import{execFileSync}from'node:child_process';import{createHash}from'node:crypto';
const base='20a1d3ccb4f63c7fcacd2fc90d5d0fa50b820a26',folder='docs/mobile-keyboard-icon-fit-20261101/';
const git=(...a)=>execFileSync('git',a,{maxBuffer:128e6}),sha=b=>createHash('sha256').update(b).digest('hex'),sort=a=>a.sort((a,b)=>a.localeCompare(b)),lines=b=>b.toString().trim().split('\n').filter(Boolean);
const roots=['app','components','hooks','data','lib','public','scripts','db','drizzle','.github','AGENTS.md','PUBLICATIE.md','VORMGEVING-VASTGEZET.md','docs/appearance-floor-20261031','docs/KLINK-DOCENTHANDLEIDING.md','vite.config.ts','next.config.ts','package.json','package-lock.json','wrangler.jsonc'];
export function verifyMobileKeyboardIconFitRelease(read=readFileSync){
 const r=JSON.parse(read('docs/klink-owner-release-mobile-keyboard-icon-fit-20261101.json'));assert.equal(r.approvedBy,'Nico');assert(r.publicationApproved&&r.appearanceChangeApproved);assert.equal(r.baselineSourceCommit,base);assert.equal(r.liveSourceCommit,base);assert(r.userRequest.includes('knoopjes kleiner'));git('merge-base','--is-ancestor',base,'HEAD');
 const changed=sort([...new Set([...lines(git('diff','--name-only',base,'--',...roots)),...lines(git('ls-files','--others','--exclude-standard','--',...roots))])]);assert.deepEqual(changed,sort([...r.changedFiles,'docs/appearance-floor-20261031/floor.json',r.approval]));assert.deepEqual(sort(Object.keys(r.files)),r.changedFiles);for(const f of r.changedFiles)assert.equal(sha(read(f)),r.files[f],f);
 assert.equal(git('diff','--name-only',base,'--','components','hooks','data','lib','public','db','drizzle','.github','package.json','package-lock.json','wrangler.jsonc').length,0,'Keyboard behavior, content, audio, progress and dependencies stay unchanged');
 const before=git('show',base+':app/learner-layout.css').toString();assert.equal(read('app/learner-layout.css').toString(),before.replace('    .cp-exercise-record-head nav button, .cp-exercise-listen, .cp-view-toggle { width: 44px; height: 44px; min-width: 44px; }','    .cp-exercise-record-head nav button, .cp-exercise-listen, .cp-view-toggle { width: 44px; height: 44px; min-width: 44px; }\n    .cp-exercise-tools .cp-view-toggle { padding: 0; }\n    .cp-view-toggle > span { width: 44px; height: 44px; }'));
 const floor=JSON.parse(read('docs/appearance-floor-20261031/floor.json')),old=JSON.parse(git('show',base+':docs/appearance-floor-20261031/floor.json'));assert.deepEqual({...floor,approvedUpdates:old.approvedUpdates},old);assert.deepEqual(floor.approvedUpdates,[...old.approvedUpdates,r.approval]);assert.deepEqual(JSON.parse(read(r.approval)).files,r.files);
 const checks=JSON.parse(read(folder+'checks.json'));assert.equal(checks.checks.length,438);assert.equal(checks.native.length,2);assert.deepEqual(checks.errors,[]);for(const c of checks.checks)for(const k of['allControlsFullyVisible','touchTargets44','stageFits','atTop','noHorizontalScroll','outerFits','modelFits','oldProgressPreserved'])assert(c[k],k);
 const backup=JSON.parse(read(folder+'backup.json'));assert(backup.verified&&backup.fullReadback&&backup.zipIntegrity&&backup.driveId);assert.deepEqual(backup.files,r.files);return r;
}
export function readBeforeMobileKeyboardIconFit(file,r,read=readFileSync){return r.changedFiles.includes(file)||file==='docs/appearance-floor-20261031/floor.json'?git('show',base+':'+file):read(file);}
